"use client";

import { m, type Variants } from "framer-motion";
import { Code, Server, Database, Wrench, Layers } from "lucide-react";
import { skillsInfo } from "@/lib/portfolio-data";
import { SectionHeading } from "@/components/ui/section-heading";
import { ease } from "@/lib/motion";
import type { ReactNode } from "react";

const categoryVariants: Variants = {
  hidden: { opacity: 0, y: 24 },
  visible: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.5, ease },
  },
};

const categoryIcons: Record<string, ReactNode> = {
  "Frontend Development": <Code size={20} />,
  "Backend Development": <Server size={20} />,
  Database: <Database size={20} />,
  "Tools & Technologies": <Wrench size={20} />,
};

const levelPercentages: Record<string, number> = {
  Beginner: 40,
  Intermediate: 65,
  Advanced: 85,
  Expert: 100,
};

export function SkillsSection() {
  return (
    <section id="skills" className="relative px-6">
      <div className="mx-auto max-w-[var(--container-max)]">
        <SectionHeading title={skillsInfo.title} eyebrow="Keahlian" />

        <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-4">
          {skillsInfo.categories.map((category) => (
            <m.div
              key={category.name}
              variants={categoryVariants}
              initial="hidden"
              whileInView="visible"
              viewport={{ once: true, margin: "-80px" }}
              className="flex flex-col rounded-[var(--radius-lg)] border border-border bg-surface p-6 transition-all duration-[var(--duration-normal)] ease-[var(--ease-out)] [@media(hover:hover)]:hover:-translate-y-1 [@media(hover:hover)]:hover:border-primary/40 [@media(hover:hover)]:hover:shadow-[var(--shadow-md)]"
            >
              <div className="mb-6 flex items-center gap-3">
                <div className="flex h-10 w-10 items-center justify-center rounded-[var(--radius-md)] bg-primary/10 text-primary">
                  {categoryIcons[category.name] ?? <Layers size={20} />}
                </div>
                <h3 className="text-base font-semibold text-foreground">
                  {category.name}
                </h3>
              </div>

              <ul className="flex flex-col gap-3">
                {category.technologies.map((tech) => (
                  <li
                    key={tech.name}
                    className="group flex flex-col gap-1.5 rounded-[var(--radius-md)] border border-border/70 bg-surface-elevated/40 p-2.5 transition-all duration-[var(--duration-fast)] [@media(hover:hover)]:hover:-translate-y-0.5 [@media(hover:hover)]:hover:border-primary/40 [@media(hover:hover)]:hover:bg-primary/5"
                  >
                    <div className="flex items-center justify-between text-xs">
                      <span className="font-medium text-foreground">
                        {tech.name}
                      </span>
                      <span className="text-[10px] font-semibold uppercase tracking-wider text-foreground-subtle">
                        {tech.level}
                      </span>
                    </div>

                    <div className="h-1 w-full overflow-hidden rounded-full bg-border/60">
                      <m.div
                        className="h-full rounded-full bg-gradient-to-r from-primary/80 to-primary"
                        initial={{ scaleX: 0 }}
                        whileInView={{ scaleX: 1 }}
                        viewport={{ once: true, margin: "-40px" }}
                        transition={{ duration: 0.7, ease, delay: 0.1 }}
                        style={{
                          originX: 0,
                          width: `${levelPercentages[tech.level] || 50}%`,
                        }}
                      />
                    </div>
                  </li>
                ))}
              </ul>
            </m.div>
          ))}
        </div>
      </div>
    </section>
  );
}